  "inlineSchema": "// Gazi Portfolio — data model.\n//\n// Prisma 7 conventions: the generator is `prisma-client` with an explicit output,\n// and the datasource carries no `url` (that lives in prisma7.config.ts).\n//\n// PII note: the source CV contained an NID number, home addresses, parents' names\n// and five referees' contact details. None of that is modelled here — this backs a\n// public, crawlable website. See src/data/cv-seed.ts for the full exclusion list.\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum Role {\n  ADMIN\n}\n\nenum EmploymentType {\n  FULL_TIME\n  PART_TIME\n  CONTRACT\n  INTERNSHIP\n}\n\nenum SocialProvider {\n  LINKEDIN\n  FACEBOOK\n}\n\nenum SocialStatus {\n  DRAFT\n  QUEUED\n  POSTED\n  FAILED\n  NEEDS_RECONNECT\n}\n\nenum SocialSubject {\n  EXPERIENCE\n  PROJECT\n}\n\nenum AssetKind {\n  CV_DESIGNED\n  CV_ATS\n}\n\n/**\n * ------------------------------------------------------------------ auth ---\n */\n\nmodel User {\n  id           String    @id @default(cuid())\n  email        String    @unique\n  passwordHash String\n  name         String\n  role         Role      @default(ADMIN)\n  lastLoginAt  DateTime?\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  @@map(\"users\")\n}\n\n/**\n * --------------------------------------------------------------- content ---\n */\n\n/// Singleton row. Contact details live here rather than in env so he can change\n/// his WhatsApp number from the admin panel without a redeploy.\nmodel Profile {\n  id                String  @id @default(\"profile\")\n  fullName          String\n  headline          String\n  subheadline       String  @default(\"\")\n  summary           String  @db.Text\n  location          String  @default(\"\")\n  email             String  @default(\"\")\n  phone             String  @default(\"\")\n  whatsapp          String  @default(\"\")\n  linkedinUrl       String  @default(\"\")\n  githubUrl         String  @default(\"\")\n  facebookUrl       String  @default(\"\")\n  messengerUsername String  @default(\"\")\n  twitterUrl        String  @default(\"\")\n  websiteUrl        String  @default(\"\")\n  avatarPath        String?\n  seoTitle          String  @default(\"\")\n  seoDescription    String  @default(\"\") @db.Text\n\n  updatedAt DateTime @updatedAt\n\n  @@map(\"profile\")\n}\n\nmodel Experience {\n  id             String         @id @default(cuid())\n  slug           String         @unique\n  title          String\n  company        String\n  companyUrl     String?\n  employmentType EmploymentType @default(FULL_TIME)\n  location       String?\n  startDate      DateTime\n  endDate        DateTime?\n  isCurrent      Boolean        @default(false)\n  summary        String         @default(\"\") @db.Text\n  bullets        String[]\n  tags           String[]\n  /// Post text used for LinkedIn/Facebook publishing and the prefilled share links.\n  shareText      String         @default(\"\") @db.Text\n  order          Int            @default(0)\n  isPublished    Boolean        @default(true)\n\n  dispatches SocialDispatch[] @relation(\"ExperienceDispatches\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([isPublished, order])\n  @@map(\"experiences\")\n}\n\nmodel Education {\n  id        String  @id @default(cuid())\n  school    String\n  degree    String\n  field     String?\n  startYear Int\n  endYear   Int\n  details   String? @db.Text\n  order     Int     @default(0)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([order])\n  @@map(\"educations\")\n}\n\nmodel Skill {\n  id       String @id @default(cuid())\n  name     String @unique\n  category String @default(\"General\")\n  level    Int?\n  order    Int    @default(0)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([category, order])\n  @@map(\"skills\")\n}\n\nmodel Certification {\n  id       String    @id @default(cuid())\n  name     String\n  issuer   String    @default(\"\")\n  issuedOn DateTime?\n  url      String?\n  order    Int       @default(0)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([order])\n  @@map(\"certifications\")\n}\n\nmodel Project {\n  id          String   @id @default(cuid())\n  slug        String   @unique\n  title       String\n  summary     String   @db.Text\n  body        String   @default(\"\") @db.Text\n  role        String?\n  client      String?\n  year        Int?\n  liveUrl     String?\n  repoUrl     String?\n  techStack   String[]\n  coverPath   String?\n  featured    Boolean  @default(false)\n  order       Int      @default(0)\n  isPublished Boolean  @default(true)\n  shareText   String   @default(\"\") @db.Text\n\n  images     ProjectImage[]\n  dispatches SocialDispatch[] @relation(\"ProjectDispatches\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([isPublished, featured, order])\n  @@map(\"projects\")\n}\n\nmodel ProjectImage {\n  id        String  @id @default(cuid())\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  path    String\n  alt     String  @default(\"\")\n  caption String?\n  width   Int     @default(0)\n  height  Int     @default(0)\n  order   Int     @default(0)\n\n  createdAt DateTime @default(now())\n\n  @@index([projectId, order])\n  @@map(\"project_images\")\n}\n\n/**\n * ---------------------------------------------------------------- social ---\n */\n\nmodel SocialAccount {\n  id       String         @id @default(cuid())\n  provider SocialProvider @unique\n\n  /// AES-256-GCM ciphertext. Never plaintext — encryptSecret() refuses without a key.\n  accessTokenEnc  String    @db.Text\n  refreshTokenEnc String?   @db.Text\n  expiresAt       DateTime?\n\n  /// LinkedIn member URN, or the Facebook Page id.\n  accountRef  String\n  displayName String @default(\"\")\n  scopes      String @default(\"\")\n\n  connectedAt DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@map(\"social_accounts\")\n}\n\nmodel SocialDispatch {\n  id String @id @default(cuid())\n\n  subjectType SocialSubject\n  subjectId   String\n\n  /// Convenience relations so a dispatch can be found from either content type.\n  experienceId String?\n  experience   Experience? @relation(\"ExperienceDispatches\", fields: [experienceId], references: [id], onDelete: Cascade)\n  projectId    String?\n  project      Project?    @relation(\"ProjectDispatches\", fields: [projectId], references: [id], onDelete: Cascade)\n\n  provider SocialProvider\n  status   SocialStatus   @default(DRAFT)\n  message  String         @db.Text\n\n  externalId String?\n  permalink  String?\n  error      String?   @db.Text\n  attempts   Int       @default(0)\n  postedAt   DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([subjectType, subjectId])\n  @@index([status])\n  @@map(\"social_dispatches\")\n}\n\n/**\n * ------------------------------------------------------- generated assets ---\n */\n\n/// Cached CV PDFs. `sourceHash` covers every CV-relevant field, so an admin edit\n/// changes it and the asset is regenerated — that is what makes \"the visitor\n/// always downloads an up-to-date CV\" true rather than hoped for.\nmodel GeneratedAsset {\n  id   String    @id @default(cuid())\n  kind AssetKind @unique\n\n  path       String\n  bytes      Int     @default(0)\n  sha256     String  @default(\"\")\n  sourceHash String  @default(\"\")\n  error      String? @db.Text\n\n  generatedAt DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@map(\"generated_assets\")\n}\n",
